    "investigate": [
        {
            "tool": "sql",
            "query": "SELECT p.id, p.order_id, p.created_at, o.id as order_id, o.created_at as order_created, o.status as order_status FROM payments p JOIN orders o ON p.order_id = o.id WHERE p.status = 'captured' AND o.status != 'confirmed' AND p.created_at > :now - 300 LIMIT 10",
            "why": "Check if payments are being captured for orders that exist but are not in 'confirmed' status, which would explain the invariant violation"
        }
    ],
    "hypotheses": [
        {
            "service": "payment-service",
            "kind": "bad_deploy",
            "mechanism": "The payment-service v1.1 deploy at t=564 introduced a bug that captures payments for orders that are not yet confirmed, violating the 2-minute confirmation requirement",
            "supporting": ["E1", "E8", "E9", "E14"],
            "refuting": ["E31", "E32"],
            "explains": ["I1_payment_has_order"],
            "repair_plan": [
                {
                    "action": "rollback_service",
                    "params": {
                        "service": "payment-service"
                    }
                },
                {
                    "action": "replay_payment_confirmations",
                    "params": {}
                }
            ]
        }
    ],
    "summary": "Payment-service v1.1 deploy captures payments before orders are confirmed, violating the 2-minute confirmation requirement."
}
